import{_ as e,o as s,c as i,a8 as t}from"./chunks/framework.CNIpabDg.js";const k=JSON.parse('{"title":"Submit a package declaration","description":"Contribute reviewed package metadata to the static, unsigned community registry preview.","frontmatter":{"layout":"doc","docType":"how-to","description":"Contribute reviewed package metadata to the static, unsigned community registry preview."},"headers":[],"relativePath":"how-to/submit-package.md","filePath":"how-to/submit-package.md","lastUpdated":1793045410000}'),n={name:"how-to/submit-package.md"};function l(r,a,o,p,h,d){return s(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793045410000"},[...a[0]||(a[0]=[t(`<h1 id="submit-a-package-declaration" tabindex="-1">Submit a package declaration <a class="header-anchor" href="#submit-a-package-declaration" aria-label="Permalink to &quot;Submit a package declaration&quot;">​</a></h1><p>The <a href="https://github.com/xila-project/registry" target="_blank" rel="noreferrer"><code>xila-project/registry</code></a> repository provides a <strong>development-only registry preview</strong>, not an installable app store. You can submit metadata for an existing external release; publishing a declaration does <strong>not</strong> download, verify signatures, run, or install your code.</p><h2 id="_1-publish-the-archive-outside-git" tabindex="-1">1. Publish the archive outside Git <a class="header-anchor" href="#_1-publish-the-archive-outside-git" aria-label="Permalink to &quot;1. Publish the archive outside Git&quot;">​</a></h2><p>Build the experimental archive with the <a href="./package-application.html">native package builder</a>. Host the immutable <code>.xpk</code> as an external release asset, for example on your project&#39;s GitHub Releases. Record its <strong>real</strong> HTTPS URL, file length and SHA-256; do not use the example&#39;s fake values. The current registry code validates the <em>shape</em> of these fields but does not fetch artifacts to verify the actual bytes.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/released.xpk</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/released.xpk</span></span></code></pre></div><p>Keep the release artifact immutable. Publish a new package version for changed bytes rather than silently replacing an older artifact.</p><h2 id="_2-add-a-versioned-toml-declaration" tabindex="-1">2. Add a versioned TOML declaration <a class="header-anchor" href="#_2-add-a-versioned-toml-declaration" aria-label="Permalink to &quot;2. Add a versioned TOML declaration&quot;">​</a></h2><p>Clone <code>registry</code>, then create:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/&lt;namespace&gt;/&lt;application&gt;/&lt;version&gt;.toml</span></span></code></pre></div><p>For <code>community.weather</code> version <code>1.0.0</code>, the location is <code>packages/community/weather/1.0.0.toml</code>. Start from <a href="https://github.com/xila-project/registry/blob/main/examples/weather-1.0.0.toml" target="_blank" rel="noreferrer">the example</a> and replace every placeholder:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">schema = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;community.weather&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">version = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.0.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">summary = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;An example weather application&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">license = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MIT&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">source = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/example/weather&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">artifacts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">target = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wasm32-wasip1&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">minimum_xila_abi = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">url = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://github.com/example/weather/releases/download/v1.0.0/weather.xpk&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sha256 = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">size = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10240</span></span></code></pre></div><p><strong>All URLs, hashes and sizes above are fictitious</strong>; they must be replaced with the actual release details before submitting. This <strong>TOML publication declaration</strong> is not the internal <strong>JSON package manifest</strong> described in <a href="/reference/package-format.html">Package format</a>.</p><p>The identifier must match its directory path. Valid namespace and application components are lowercase words/digits with internal hyphens. Each package version must use compatible SemVer without build metadata. Artifact targets must be distinct within one declaration and the SHA-256 value must be lowercase hexadecimal. The <code>xila</code> namespace is reserved for first-party applications <strong>by convention</strong>, but no authenticated publisher policy enforces it yet.</p><h2 id="_3-validate-locally" tabindex="-1">3. Validate locally <a class="header-anchor" href="#_3-validate-locally" aria-label="Permalink to &quot;3. Validate locally&quot;">​</a></h2><p>The registry uses <strong>Python 3.12+</strong>, only standard-library modules, and no external services:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unittest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/registry.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/registry.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>The output under <code>_site/v1</code> is a deterministic unsigned JSON preview. Each package has a direct descriptor such as <code>v1/packages/community/weather.json</code>; there is no full catalog, search server or dependency resolver. <code>v1/registry.json</code> contains only metadata including package count.</p><p>The registry starts with <strong>zero live declarations</strong>. Its <code>examples/weather-1.0.0.toml</code> is illustrative and is not published by the builder.</p><h2 id="_4-open-a-pull-request" tabindex="-1">4. Open a pull request <a class="header-anchor" href="#_4-open-a-pull-request" aria-label="Permalink to &quot;4. Open a pull request&quot;">​</a></h2><p>A GitHub Actions workflow runs tests, validates the TOML, and uploads the generated preview for review. Maintainers should review <strong>publisher identity, provenance, artifact permissions and release immutability</strong>; successful CI checks are not a signature or security review. An optional GitHub Pages workflow runs on merged <code>main</code> (or manual dispatch) and publishes <strong>unsigned</strong> JSON.</p><p>To enable Pages, maintainers must select <strong>Settings → Pages → Build and deployment → GitHub Actions</strong>. Protect <code>main</code> with required checks and review before accepting external submissions. Publishing never compiles or executes submitted application code.</p><h2 id="current-limitations" tabindex="-1">Current limitations <a class="header-anchor" href="#current-limitations" aria-label="Permalink to &quot;Current limitations&quot;">​</a></h2><p>No end-to-end authenticated publication chain, official keyring, stable signed index, repository search, package installation or on-device <code>pkg</code> CLI is available yet. A valid SHA-256 field inside unsigned JSON cannot establish trustworthy publisher identity. See <a href="/explanation/package-management.html">the package-management architecture</a> for the separation between repository metadata, signed package contents and loader authorization.</p>`,23)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
